package com.learn.hub.pricing;

import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import org.springframework.stereotype.Component;

sealed interface DiscountStrategy permits NoDiscount, MemberDiscount, CouponDiscount {
    String channel();

    BigDecimal apply(BigDecimal amount);
}

record NoDiscount() implements DiscountStrategy {
    public String channel() { return "none"; }
    public BigDecimal apply(BigDecimal amount) { return amount; }
}

record MemberDiscount(int level) implements DiscountStrategy {
    public String channel() { return "member"; }
    public BigDecimal apply(BigDecimal amount) {
        return amount.multiply(BigDecimal.valueOf(1 - level * 0.05));
    }
}

record CouponDiscount(BigDecimal off) implements DiscountStrategy {
    public String channel() { return "coupon"; }
    public BigDecimal apply(BigDecimal amount) {
        return amount.subtract(off).max(BigDecimal.ZERO);
    }
}

@Component
class DiscountStrategies {
    private final Map<String, DiscountStrategy> byChannel;
    DiscountStrategies(List<DiscountStrategy> strategies) {
        this.byChannel = strategies.stream()
                .collect(Collectors.toMap(DiscountStrategy::channel, strategy -> strategy));
    }

    BigDecimal price(String channel, BigDecimal amount) {
        return byChannel.getOrDefault(channel, new NoDiscount()).apply(amount);
    }
}

package com.learn.hub.order;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

/** 状态迁移显式成表，新增状态必须同时给出入口与出口。 */
final class OrderStateMachine {

    enum Status { CREATED, PAID, SHIPPED, CLOSED, REFUNDED }

    private static final Map<Status, Set<Status>> ALLOWED = new EnumMap<>(Status.class);

    static {
        ALLOWED.put(Status.CREATED, EnumSet.of(Status.PAID, Status.CLOSED));
        ALLOWED.put(Status.PAID, EnumSet.of(Status.SHIPPED, Status.REFUNDED));
        ALLOWED.put(Status.SHIPPED, EnumSet.of(Status.CLOSED));
        ALLOWED.put(Status.CLOSED, EnumSet.noneOf(Status.class));
        ALLOWED.put(Status.REFUNDED, EnumSet.noneOf(Status.class));
    }

    private Status state = Status.CREATED;

    Status move(Status target) {
        Set<Status> next = ALLOWED.get(state);
        if (next == null || !next.contains(target)) {
            throw new IllegalStateException("非法迁移: " + state + " -> " + target);
        }
        state = target;
        return state;
    }

    Status current() {
        return state;
    }
}

export type LearningEvent =
  | { type: 'enrolled'; topicId: string }
  | { type: 'completed'; topicId: string }
  | { type: 'reset' };

export interface LearningView {
  enrolled: number;
  completed: number;
  lastTopic?: string;
}

type Listener = (view: LearningView) => void;

const empty = (): LearningView => ({ enrolled: 0, completed: 0 });

function reduce(view: LearningView, event: LearningEvent): LearningView {
  switch (event.type) {
    case 'enrolled':
      return { ...view, enrolled: view.enrolled + 1, lastTopic: event.topicId };
    case 'completed':
      return { ...view, completed: view.completed + 1, lastTopic: event.topicId };
    case 'reset':
      return empty();
  }
}

/** 门面：调用方不关心写接口、重试与订阅者的注册细节。 */
export class LearningFacade {
  private view = empty();
  private readonly listeners = new Set<Listener>();
  constructor(private readonly post: (event: LearningEvent) => Promise<void>) {}

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    listener(this.view);
    return () => this.listeners.delete(listener);
  }

  async dispatch(event: LearningEvent): Promise<void> {
    await this.post(event);
    this.view = reduce(this.view, event);
    this.listeners.forEach((listener) => listener(this.view));
  }
}
